export type experimentAnnotationsLogicType = MakeLogicType<
    experimentAnnotationsLogicValues,
    experimentAnnotationsLogicActions,
    ExperimentAnnotationsLogicProps,
    experimentAnnotationsLogicMeta
>

export const experimentAnnotationsLogic: LogicWrapper<experimentAnnotationsLogicType> =
    kea<experimentAnnotationsLogicType>([
        props({} as ExperimentAnnotationsLogicProps),
        key(({ experimentId }) => experimentId),
        path((key) => ['products', 'experiments', 'frontend', 'annotations', 'experimentAnnotationsLogic', key]),
        connect({ values: [teamLogic, ['currentProjectId']] }),
        actions({
            setVariantKey: (variantKey: string) => ({ variantKey }),
            setContent: (content: string) => ({ content }),
            editAnnotation: (annotation: ExperimentAnnotationApi) => ({ annotation }),
            cancelEditing: true,
            requestDelete: (annotationId: number | null) => ({ annotationId }),
        }),
        loaders(({ props, values }) => ({
            annotations: [
                null as ExperimentAnnotationApi[] | null,
                {
                    loadExperimentAnnotations: async (): Promise<ExperimentAnnotationApi[]> =>
                        api.experimentsAnnotationsList(String(values.currentProjectId), props.experimentId),
                },
            ],
            savedAnnotation: [
                null as ExperimentAnnotationApi | null,
                {
                    saveExperimentAnnotation: async (): Promise<ExperimentAnnotationApi> => {
                        const payload = { variant_key: values.variantKey, content: values.content.trim() }
                        return values.editingAnnotationId === null
                            ? api.experimentsAnnotationsCreate(
                                  String(values.currentProjectId),
                                  props.experimentId,
                                  payload
                              )
                            : api.experimentsAnnotationsPartialUpdate(
                                  String(values.currentProjectId),
                                  props.experimentId,
                                  String(values.editingAnnotationId),
                                  payload
                              )
                    },
                },
            ],
            deletedAnnotationId: [
                null as number | null,
                {
                    deleteExperimentAnnotation: async (): Promise<number | null> => {
                        const annotationId = values.pendingDeleteId
                        if (annotationId !== null) {
                            await api.experimentsAnnotationsDestroy(
                                String(values.currentProjectId),
                                props.experimentId,
                                String(annotationId)
                            )
                        }
                        return annotationId
                    },
                },
            ],
        })),
        reducers({
            variantKey: [
                '',
                {
                    setVariantKey: (_, { variantKey }) => variantKey,
                    editAnnotation: (_, { annotation }) => annotation.variant_key,
                },
            ],
            content: [
                '',
                {
                    setContent: (_, { content }) => content,
                    editAnnotation: (_, { annotation }) => annotation.content,
                    cancelEditing: () => '',
                    saveExperimentAnnotationSuccess: () => '',
                },
            ],
            editingAnnotationId: [
                null as number | null,
                {
                    editAnnotation: (_, { annotation }) => annotation.id,
                    cancelEditing: () => null,
                    saveExperimentAnnotationSuccess: () => null,
                },
            ],
            pendingDeleteId: [
                null as number | null,
                {
                    requestDelete: (_, { annotationId }) => annotationId,
                    deleteExperimentAnnotationSuccess: () => null,
                },
            ],
            annotationsError: [
                false,
                {
                    loadExperimentAnnotations: () => false,
                    loadExperimentAnnotationsFailure: () => true,
                    loadExperimentAnnotationsSuccess: () => false,
                },
            ],
            annotations: {
                saveExperimentAnnotationSuccess: (state: ExperimentAnnotationApi[] | null, { savedAnnotation }) =>
                    state?.some((annotation) => annotation.id === savedAnnotation.id)
                        ? state.map((annotation) =>
                              annotation.id === savedAnnotation.id ? savedAnnotation : annotation
                          )
                        : [savedAnnotation, ...(state ?? [])],
                deleteExperimentAnnotationSuccess: (state: ExperimentAnnotationApi[] | null, { deletedAnnotationId }) =>
                    state?.filter((annotation) => annotation.id !== deletedAnnotationId) ?? null,
            },
        }),
        selectors({
            mutationLoading: [
                (s) => [s.savedAnnotationLoading, s.deletedAnnotationIdLoading],
                (saving: boolean, deleting: boolean): boolean => saving || deleting,
            ],
        }),
        listeners(({ actions, values }) => ({
            deleteExperimentAnnotationSuccess: ({ deletedAnnotationId }) => {
                if (values.editingAnnotationId === deletedAnnotationId) {
                    actions.cancelEditing()
                }
            },
        })),
        afterMount(({ actions }) => actions.loadExperimentAnnotations()),
    ])
